class Solution {
  public boolean isDigitorialPermutation(int n) {
    char[] target = Integer.toString(n).toCharArray();
    java.util.Arrays.sort(target);
    for (int d : new int[] {1, 2, 145, 40585}) {
      char[] c = Integer.toString(d).toCharArray();
      java.util.Arrays.sort(c);
      if (java.util.Arrays.equals(c, target)) return true;
    }
    return false;
  }
}
